const media=(role,id='default',options={})=>root.SpaMedia?.image(role,id,options)||'';
const mediaFrame=(role,id='default',options={})=>root.SpaMedia?.frame(role,id,options)||'';
const hero=(c,role,id,tag,heading,desc='')=>`${mediaFrame(role,id,{alt:heading})}<p class="eyebrow">${esc(c,text(c,tag))}</p><h1 tabindex="-1">${esc(c,heading)}</h1>${desc?`<p class="muted">${esc(c,desc)}</p>`:''}`;
const sum=(c,rows)=>`<dl class="summary-list">${rows.map(([k,v])=>`<div><dt>${esc(c,text(c,k))}</dt><dd>${v}</dd></div>`).join('')}</dl>`;
const now=c=>Date.parse(c.state.now),plus=(d,n)=>new Date(Date.parse(d+'T12:00:00Z')+n*864e5).toISOString().slice(0,10);
const ui=c=>c.session.ui||{},update=(c,p)=>c.patch({ui:{...ui(c),...p}}),rows=(c,k)=>c.owned(k)||[];
const fdata=c=>ui(c).facilityDraft||{},fac=(c,id)=>c.C.facilities?.find(x=>x.id===id);
const localized=(c,x)=>c.name(x?.names||x?.name||x||'');
const categoryName=(c,id)=>localized(c,c.C.cafeCategories?.find(x=>x.id===id)||id);
const dayStrip=(c,d)=>`<div class="revision-day-strip">${Array.from({length:7},(_,i)=>{const v=plus(c.today(),i+1);return `<button class="revision-day ${v===d?'selected':''}" type="button" data-action="revision-facility-date" data-id="${v}"><span>${esc(c,new Date(v+'T12:00:00Z').toLocaleDateString(lang(c),{weekday:'short',timeZone:'Asia/Baku'}))}</span><strong>${v.slice(-2)}</strong></button>`;}).join('')}</div>`;
