function facilityVisits(c,id){if(!c.cid()){c.requireAuth(id?'facility-visit/'+id:'facility-visits');return '';}if(id){
 const x=rows(c,'facilityAccess').find(x=>x.id===id);if(!x)return title(c,'facility','visits')+empty(c);
 const copy=(tr,az,ru)=>[tr,az,ru][['tr','az','ru'].indexOf(lang(c))]||tr,glyph=(name,fallback='visits')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback),snapshot=x.snapshot||{},name=localized(c,snapshot.names||x.name||snapshot.name||text(c,'facility')),status=x.status==='confirmed'&&x.cancelRequested?'cancel_requested':x.status,areas=snapshot.includedAreas||[],outcome=x.cancelOutcome,entered=!!x.checkedInAt||x.status==='checked-in',entryLabel=x.status==='expired'?text(c,'expired'):facilityText(c,entered?'entryRecorded':x.status==='cancelled'?'cancelApproved':'beforeEntry'),day=Number.isFinite(Date.parse(x.date+'T12:00:00Z'))?new Intl.DateTimeFormat(lang(c),{timeZone:'Asia/Baku',day:'numeric',month:'long',year:'numeric'}).format(new Date(x.date+'T12:00:00Z')):c.date(x.date);
 return `<section class="facilityfix facility-source-visit" data-source="facility_visit"><header class="facility-source-header" data-source="header_001"><div><a class="icon-button" href="#visits" aria-label="${esc(c,text(c,'back'))}">${glyph('lucide:chevron-left','back')}</a><span class="facility-source-status ${status==='checked-in'?'is-entered':status==='cancel_requested'?'is-pending':''}" data-status="${esc(c,status)}">${esc(c,text(c,status))}</span></div><p>${esc(c,copy('Ziyaret Detayı','Ziyarət məlumatları','Сведения о визите'))}</p><h1 tabindex="-1">${esc(c,copy('Tesis Girişi','Məkana Giriş','Вход в комплекс'))}</h1></header><div class="facility-source-content"><section class="facility-source-time" data-source="visit-time-card_003"><div><span class="facility-source-icon">${glyph('solar:clock-circle-bold')}</span><div><p>${esc(c,facilityText(c,'window'))}</p><strong>${esc(c,x.time)}–${esc(c,facilityEnd(x))}</strong></div></div><div><span class="facility-source-icon">${glyph('solar:calendar-bold')}</span><div><p>${esc(c,copy('Randevu Tarihi','Rezervasiya tarixi','Дата посещения'))}</p><strong>${esc(c,day)}</strong></div></div></section><section class="facility-source-location" data-source="location-card_004"><div><h2>Sultan Saba Baku</h2><p>${esc(c,copy('Konum ve adres bilgisi teyit bekliyor.','Məkan və ünvan məlumatı təsdiq gözləyir.','Местоположение и адрес ожидают подтверждения.'))}</p></div><span>${esc(c,copy('Konum bilgisi teyit bekliyor','Məkan məlumatı təsdiq gözləyir','Местоположение уточняется'))}</span></section><section class="facility-source-tracker" data-source="status-tracker_005"><h2>${esc(c,copy('Giriş Durumu','Giriş vəziyyəti','Статус входа'))}</h2><ol><li class="${entered&&!['expired','cancelled'].includes(x.status)?'is-entered':''}"><strong>${esc(c,entryLabel)}</strong>${x.checkedInAt?`<p>${esc(c,facilityStamp(c,x.checkedInAt))}</p>`:x.status==='checked-in'?`<p>${esc(c,facilityText(c,'entryTimeUnknown'))}</p>`:''}</li><li><strong>${esc(c,facilityText(c,'plannedEnd'))}: ${esc(c,facilityEnd(x))}</strong><p>${esc(c,facilityText(c,'noCheckout'))}</p></li></ol></section><details class="facility-source-details"><summary>${esc(c,name)}</summary><div>${sum(c,[['duration',(x.duration||0)+' '+esc(c,text(c,'minutes'))],['total',c.money(x.priceMinor||0)]])}${areas.length?`<section class="facilityfix-retained-scope"><h3>${esc(c,text(c,'scope'))}</h3><div class="facilityfix-scope">${areas.map(a=>`<span>${esc(c,text(c,a))}</span>`).join('')}</div></section>`:''}${x.createdAt?`<p><strong>${esc(c,facilityText(c,'reservedAt'))}</strong><br>${esc(c,facilityStamp(c,x.createdAt))}</p>`:''}</div></details>${x.cancelRequested||outcome||x.cancelReply||x.cancelHistory?.length?`<section class="facilityfix-cancel-history"><h3>${esc(c,facilityText(c,'cancelHistory'))}</h3><p>${esc(c,x.cancelRequested&&x.status==='confirmed'?facilityText(c,'pendingCancel'):outcome==='approved'?facilityText(c,'cancelApproved'):outcome==='rejected'?facilityText(c,'cancelRejected'):outcome==='superseded'||x.cancelRequested?facilityText(c,'cancelSuperseded'):text(c,'reply'))}</p>${x.cancelResolutionCode?`<p>${esc(c,c.t('code.'+x.cancelResolutionCode.toLowerCase()))}</p>`:''}${x.cancelReply?`<p>${esc(c,x.cancelReply)}</p>`:''}${x.cancelHistory?.length?`<ol>${x.cancelHistory.map(h=>`<li>${esc(c,facilityStamp(c,h.at))}${h.reasonCode?' · '+esc(c,c.t('code.'+h.reasonCode.toLowerCase())):''}${h.message?`<p>${esc(c,h.message)}</p>`:''}</li>`).join('')}</ol>`:''}</section>`:''}${x.visitId?a(c,'visit','visit/'+x.visitId,'secondary'):''}${!simplified(c)&&x.status==='confirmed'&&!x.cancelRequested?form('revision-facility-cancel',hidden(c,'id',x.id)+area(c,'reason')+`<p class="small muted">${esc(c,text(c,'cancelWarning'))}</p>`+submit(c,'cancel')):''}${a(c,'calendar','discover/facilities','secondary')}</div></section>`;
}
let list=rows(c,'facilityAccess');if(id)list=list.filter(x=>x.id===id);return `<div class="facilityfix facilityfix-visit" data-source="facility_visit">${title(c,id?'facility':'accesses','visits')}${list.length?list.map(x=>{const snapshot=x.snapshot||{},name=localized(c,snapshot.names||x.name||snapshot.name||text(c,'facility')),status=x.status==='confirmed'&&x.cancelRequested?'cancel_requested':x.status,areas=snapshot.includedAreas||[],outcome=x.cancelOutcome;return `<article class="facilityfix-record"><div class="row">${badge(c,status)}</div><h2>${esc(c,name)}</h2><section class="facilityfix-time-card" data-source="visit-time-card_003"><div>${c.icon('visits')}<span><small>${esc(c,facilityText(c,'window'))}</small><strong>${esc(c,x.time)}–${esc(c,facilityEnd(x))}</strong></span></div><div>${c.icon('visits')}<span><small>${esc(c,text(c,'date'))}</small><strong>${esc(c,c.date(x.date))}</strong></span></div>${sum(c,[['duration',(x.duration||0)+' '+esc(c,text(c,'minutes'))],['total',c.money(x.priceMinor||0)]])}</section>${areas.length?`<section class="facilityfix-retained-scope"><h3>${esc(c,text(c,'scope'))}</h3><div class="facilityfix-scope">${areas.map(a=>`<span>${esc(c,text(c,a))}</span>`).join('')}</div></section>`:''}<section class="facilityfix-timeline" data-source="status-tracker_005"><h3>${esc(c,text(c,'status'))}</h3><ol>${x.createdAt?`<li><strong>${esc(c,facilityText(c,'reservedAt'))}</strong><p>${esc(c,facilityStamp(c,x.createdAt))}</p></li>`:''}<li><strong>${esc(c,x.status==='expired'?text(c,'expired'):facilityText(c,x.checkedInAt||x.status==='checked-in'?'entryRecorded':x.status==='cancelled'?'cancelApproved':'beforeEntry'))}</strong>${x.checkedInAt?`<p>${esc(c,facilityStamp(c,x.checkedInAt))}</p>`:x.status==='checked-in'?`<p>${esc(c,facilityText(c,'entryTimeUnknown'))}</p>`:''}</li><li><strong>${esc(c,facilityText(c,'plannedEnd'))}: ${esc(c,facilityEnd(x))}</strong><p>${esc(c,facilityText(c,'noCheckout'))}</p></li></ol></section>${x.cancelRequested||outcome||x.cancelReply||x.cancelHistory?.length?`<section class="facilityfix-cancel-history"><h3>${esc(c,facilityText(c,'cancelHistory'))}</h3><p>${esc(c,x.cancelRequested&&x.status==='confirmed'?facilityText(c,'pendingCancel'):outcome==='approved'?facilityText(c,'cancelApproved'):outcome==='rejected'?facilityText(c,'cancelRejected'):outcome==='superseded'||x.cancelRequested?facilityText(c,'cancelSuperseded'):text(c,'reply'))}</p>${x.cancelResolutionCode?`<p>${esc(c,c.t('code.'+x.cancelResolutionCode.toLowerCase()))}</p>`:''}${x.cancelReply?`<p>${esc(c,x.cancelReply)}</p>`:''}${x.cancelHistory?.length?`<ol>${x.cancelHistory.map(h=>`<li>${esc(c,facilityStamp(c,h.at))}${h.reasonCode?' · '+esc(c,c.t('code.'+h.reasonCode.toLowerCase())):''}${h.message?`<p>${esc(c,h.message)}</p>`:''}</li>`).join('')}</ol>`:''}</section>`:''}${x.visitId?a(c,'visit','visit/'+x.visitId,'secondary'):''}${!simplified(c)&&x.status==='confirmed'&&!x.cancelRequested?form('revision-facility-cancel',hidden(c,'id',x.id)+area(c,'reason')+`<p class="small muted">${esc(c,text(c,'cancelWarning'))}</p>`+submit(c,'cancel')):''}</article>`;}).join(''):empty(c)}${a(c,'calendar','discover/facilities','secondary')}</div>`;}

