function quoteLines(c,items){return `<div class="revision-itinerary">${items.map(x=>{const service=c.C.services.find(s=>s.id===x.serviceId),cl=c.C.classes.find(s=>s.id===x.classId);return `<div><strong>${esc(c,localized(c,x.snapshot?.serviceNames||x.snapshot?.names||x.name||service||cl||x))}</strong><span>${x.date?esc(c,c.date(x.date)):''} ${esc(c,x.time||'')}</span>${x.duration?`<span>${x.duration} ${esc(c,text(c,'minutes'))}</span>`:''}${x.specialistId?`<span>${esc(c,localized(c,c.C.specialists.find(p=>p.id===x.specialistId)||x.specialistId))}</span>`:''}${x.amountMinor!==undefined?`<span>${c.money(x.amountMinor)}</span>`:''}</div>`;}).join('')}</div>`;}
function decisionForm(c,kind,id){return form('revision-quote-decision',hidden(c,'kind',kind)+hidden(c,'id',id)+area(c,'reason')+select(c,'decision',[['revise',text(c,'revise')],['decline',text(c,'decline')]])+submit(c,'request'));}
function planView(c,id){if(!c.cid()){c.requireAuth('program-plan/'+id);return '';}const p=rows(c,'programPlans').find(x=>x.id===id);if(!p)return title(c,'plan','consultations')+empty(c);const copy=(tr,az,ru)=>[tr,az,ru][['tr','az','ru'].indexOf(lang(c))]||tr;const list=rows(c,'bookings').filter(b=>p.bookingIds?.includes(b.id)||b.programPlanId===id).sort((a,b)=>(a.date+a.time).localeCompare(b.date+b.time)),done=list.filter(b=>b.status==='completed').length,percent=list.length?Math.round(done/list.length*100):0,next=list.find(b=>b.status==='confirmed'),consult=rows(c,'programConsultations').find(x=>x.id===p.consultationId);return `<header class="programfix-source-header programfix-plan-header" data-source="header_001"><a class="icon-button" href="#${consult?'consultation/'+esc(c,consult.id):'consultations'}" aria-label="${esc(c,text(c,'back'))}">${c.icon('back')}</a><h1 tabindex="-1">${esc(c,programName(c,consult)||localized(c,p))}</h1></header>`+`<section class="programfix programfix-plan" data-source="program_plan"><section class="revision-progress card programfix-progress" data-source="progress-card_003"><div class="programfix-progress-top"><div class="programfix-progress-heading"><h3>${esc(c,copy('Program İlerlemesi','Proqramın gedişi','Прогресс программы'))}</h3><strong>${done}/${list.length} ${esc(c,copy('Seans Tamamlandı','Seans Tamamlandı','сеансов выполнено'))}</strong></div><span class="programfix-progress-ring" role="progressbar" aria-label="${esc(c,text(c,'progress'))}" aria-valuemin="0" aria-valuemax="${Math.max(1,list.length)}" aria-valuenow="${done}" aria-valuetext="${done} / ${list.length} ${esc(c,copy('Seans Tamamlandı','Seans Tamamlandı','сеансов выполнено'))} (${percent}%)" style="--program-progress:${percent}%">${percent}%</span></div><p>${next?esc(c,programText(c,'nextSession'))+': '+esc(c,c.L.date(next.date,lang(c),{year:'numeric'}))+', '+esc(c,localized(c,next.snapshot?.serviceNames||next.snapshot?.names||c.C.services.find(s=>s.id===next.serviceId)||c.C.classes.find(s=>s.id===next.classId)||'')):esc(c,programText(c,'noNext'))}</p></section>${list.length?programSessionRows(c,list,true):`<p>${esc(c,programText(c,'noSessions'))}</p>`}</section><footer class="flow-footer"><div class="programfix-plan-footer">${simplified(c)?contactLinks(c):programLink(c,'supportPlan','support/programPlan/'+p.id)}${simplified(c)?'':`<p class="programfix-support-note">${esc(c,programText(c,'supportNote'))}</p>`}</div></footer>`;}


const cafeCart=c=>ui(c).cafeCart||[],cafeProduct=(c,id)=>c.C.cafeProducts?.find(p=>p.id===id),cafeTotal=c=>cafeCart(c).reduce((n,x)=>n+(cafeProduct(c,x.productId)?.priceMinor||0)*x.quantity,0);
const cafePilot=c=>!simplified(c)&&c.state.rules?.cafeOrderPilot===true;
const activeCafeVisits=c=>c.cid()&&c.M.isActiveVisit?rows(c,'visits').filter(v=>c.M.isActiveVisit(c.state,c.cid(),v.id)):[];
function visitLabel(c,v){const bookings=rows(c,'bookings').filter(b=>b.visitId===v.id&&!['cancelled','rejected'].includes(b.status)),access=rows(c,'facilityAccess').filter(x=>x.visitId===v.id&&x.status!=='cancelled');const names=[...bookings.map(b=>localized(c,c.C.services?.find(s=>s.id===b.serviceId)||c.C.classes?.find(s=>s.id===b.classId)||b.snapshot?.serviceNames||text(c,'visit'))),...access.map(x=>localized(c,fac(c,x.facilityId)||text(c,'facility')))];return [c.date(v.date),...new Set(names)].join(' · ');}
