function cafeMenu(c){const q=ui(c).menuQuery||'',cat=ui(c).menuCategory||'',all=c.C.cafeProducts||[],cats=[...new Set(all.map(p=>p.category))],list=all.filter(p=>(!cat||p.category===cat)&&[localized(c,p),localized(c,p.descriptions||p.description||'')].join(' ').toLocaleLowerCase(lang(c)).includes(q.toLocaleLowerCase(lang(c))));return `<section class="flowfix-cafe flowfix-cafe-menu">`+cafeHeader(c,text(c,'menu'))+`<form class="flowfix-menu-search" role="search" data-form="revision-menu-filter"><label class="sr-only" for="cafe-search">${esc(c,text(c,'search'))}</label><input id="cafe-search" name="search" type="search" value="${esc(c,q)}" placeholder="${esc(c,text(c,'menuSearch'))}" autocomplete="off">${hidden(c,'category',cat)}<button type="submit" aria-label="${esc(c,text(c,'search'))}">${c.icon('discover')}</button></form><div class="revision-categories">${[['',text(c,'all')],...cats.map(x=>[x,categoryName(c,x)])].map(([id,name])=>`<button type="button" class="chip ${cat===id?'selected':''}" data-action="revision-menu-category" data-id="${esc(c,id)}" aria-pressed="${cat===id}">${esc(c,name)}</button>`).join('')}</div><div class="revision-cafe-banner">${media('cafe','default',{alt:'Slim Kafe'})}<div><span>Slim Kafe</span><h2>${esc(c,text(c,'menuIntro'))}</h2></div></div><div class="revision-menu-grid">${list.map(p=>`<a href="#cafe-product/${esc(c,p.id)}" class="revision-product-card"><span class="eyebrow">${esc(c,categoryName(c,p.category))}</span><h2>${esc(c,localized(c,p))}</h2><div class="cafe-source-tile-footer"><strong>${p.priceMinor===null?esc(c,text(c,'unknownPrice')):c.money(p.priceMinor)}</strong><span class="cafe-source-tile-open" aria-hidden="true">${c.icon('right')}</span></div><span class="sr-only">${esc(c,text(c,'details'))}</span></a>`).join('')||`<p class="flowfix-menu-empty" role="status">${esc(c,text(c,'noResult'))}</p>`}</div><p class="source-note">${esc(c,text(c,'sourcePrice'))}</p>${cafeAccount(c)}${cafePilot(c)&&cafeCart(c).length?a(c,'cart','cafe-cart'):''}</section>`;}
function cafeItem(c,id){const p=cafeProduct(c,id);if(!p)return empty(c);const description=localized(c,p.descriptions||p.description||''),copy=(tr,az,ru)=>[tr,az,ru][['tr','az','ru'].indexOf(lang(c))]||tr,glyph=(name,fallback='back')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback),photo=media('cafe','default',{alt:copy('Slim Kafe sofra görünümü','Slim Kafe süfrə görünüşü','Общий вид стола Slim Kafe'),className:'cafe-source-atmosphere'}),canAdd=cafePilot(c)&&p.priceMinor!==null&&p.available!==false;return `<section class="flowfix-cafe flowfix-cafe-item cafe-source-product" data-source="cafe_product">${photo?`<figure class="cafe-source-hero" data-source="hero_002" data-media-slot="image">${photo}</figure>`:''}<a class="icon-button cafe-source-back" href="#discover/cafe" aria-label="${esc(c,text(c,'back'))}">${glyph('lucide:chevron-left')}</a>${photo?`<p class="cafe-source-caption">${esc(c,copy('Slim Kafe sofrası','Slim Kafe süfrəsi','Стол Slim Kafe'))}</p>`:''}<article class="flowfix-product-information cafe-source-information" data-source="product-detail_003"><div class="cafe-source-eyebrow">${glyph('solar:tea-cup-outline','rights')}<span>${esc(c,copy('Kafe Menü','Kafe Menyusu','Меню кафе'))}</span></div><h1 tabindex="-1">${esc(c,localized(c,p))}</h1><p class="price">${p.priceMinor===null?esc(c,text(c,'unknownPrice')):c.money(p.priceMinor)}</p>${description?`<section class="flowfix-product-description" data-source="description_004"><h2>${esc(c,text(c,'description'))}</h2><p>${esc(c,description)}</p></section>`:''}${canAdd?form('revision-cafe-add',hidden(c,'id',id)+`<div class="cafe-source-quantity" data-source="quantity_005"><h2>${esc(c,text(c,'quantity'))}</h2><div class="revision-quantity">${btn(c,'−','revision-quantity-minus','')}<label class="field"><span class="sr-only">${esc(c,text(c,'quantity'))}</span><input name="quantity" value="1" type="number" min="1" max="20" required></label>${btn(c,'+','revision-quantity-plus','')}</div></div><div class="cafe-source-location" data-source="location_006">${input(c,'location',ui(c).cafeLocation||'','text','maxlength="100"')}</div>`+submit(c,'add')):''}<p class="source-note">${esc(c,text(c,'sourcePrice'))}</p>${p.available===false?`<p class="note">${esc(c,text(c,'unavailable'))}</p>`:''}${cafeAccount(c)}</article></section>${canAdd?'':`<footer class="flow-footer"><div class="cafe-source-footer">${a(c,'goMenu','discover/cafe')}</div></footer>`}`;}
function cafeReview(c){
 if(!cafePilot(c))return `<section class="flowfix-cafe">`+cafeHeader(c,text(c,'menu'),'discover/cafe')+`<p class="note">${esc(c,text(c,'menuClosed'))}</p>`+a(c,'goMenu','discover/cafe')+cafeAccount(c)+`</section>`;
 const cart=cafeCart(c);if(!cart.length)return title(c,'cart','discover/cafe')+empty(c)+a(c,'goMenu','discover/cafe');
 const copy=(tr,az,ru)=>[tr,az,ru][['tr','az','ru'].indexOf(lang(c))]||tr;
 const glyph=(name,fallback='back')=>root.SpaSourceIcons?.[name]?.replace('<svg ','<svg class="icon source-icon" aria-hidden="true" ')||c.icon(fallback);
 const visits=activeCafeVisits(c),selectedVisit=visits.find(v=>v.id===ui(c).cafeVisitId)||visits[0];
 const priced=cart.every(x=>{const p=cafeProduct(c,x.productId);return p&&Number.isSafeInteger(p.priceMinor)&&p.priceMinor>=0&&Number.isInteger(x.quantity)&&x.quantity>0&&x.quantity<=20;});
 const selectedItemsTotal=priced?cafeTotal(c):null;
 const unpriced=copy('Menü veya fiyat bilgisi değişti. İlgili ürünü kaldırıp güncel menüden yeniden seçin.','Menyu və ya qiymət məlumatı dəyişib. Məhsulu silib cari menyudan yenidən seçin.','Состав меню или цена изменились. Удалите товар и выберите его заново в текущем меню.');
 const note=copy('Bu bir sipariş isteğidir. İşletme kabulü ve hazırlama ayrı adımlardır. Ücret yalnız teslimde ziyaret hesabına eklenir. Bu adımda ödeme alınmaz; hesap işletmede ayrıca kapatılır.','Bu sifariş sorğusudur. Müəssisənin qəbulu və hazırlama ayrı addımlardır. Məbləğ yalnız təhvil zamanı ziyarət hesabına əlavə edilir. Bu addımda ödəniş alınmır; hesab məkanda ayrıca bağlanır.','Это заявка на заказ. Принятие и приготовление — отдельные этапы. Сумма добавляется в счёт визита только при выдаче. На этом этапе оплаты нет; счёт оплачивается отдельно на месте.');
 const rowsMarkup=cart.map((x,i)=>{
  const p=cafeProduct(c,x.productId),known=p&&Number.isSafeInteger(p.priceMinor)&&p.priceMinor>=0;
  const remove=btn(c,'remove','revision-cafe-remove',i).replace('>'+esc(c,text(c,'remove'))+'</button>','>'+glyph('solar:trash-bin-trash-linear','back')+'</button>').replace('class="btn','aria-label="'+esc(c,text(c,'remove')+': '+localized(c,p||x))+'" class="btn commerce-cart-remove');
  return `<article class="commerce-cart-item" data-source="items-list_004"><div class="commerce-cart-item-title"><h2>${esc(c,p?localized(c,p):text(c,'unavailable'))}</h2>${remove}</div><div class="commerce-cart-item-price"><span>${x.quantity} × ${known?c.money(p.priceMinor):esc(c,copy('Fiyat teyit bekliyor','Qiymət təsdiq gözləyir','Цена уточняется'))}</span>${known?`<strong>${c.money(p.priceMinor*x.quantity)}</strong>`:''}</div></article>`;
 }).join('');
 const preferences=visits.length?`<details class="commerce-cart-preferences" ${String(ui(c).cafeLocation||'').trim().length<2?'open':''}><summary>${esc(c,copy('Ziyaret ve servis yerini düzenle','Ziyarəti və xidmət yerini dəyiş','Изменить визит и место подачи'))}</summary>${select(c,'activeVisit',visits.map(v=>[v.id,visitLabel(c,v)]),selectedVisit.id)}${input(c,'location',ui(c).cafeLocation||'','text','required maxlength="100"')}</details>`:'';
 const controls=!c.cid()?btn(c,'login','revision-cafe-login',''):!visits.length?`<p>${esc(c,text(c,'noVisit'))}</p>${a(c,'goMenu','discover/cafe')}`:!priced?`<p class="note error commerce-cart-unpriced" role="alert">${esc(c,unpriced)}</p>${a(c,'goMenu','discover/cafe')}`:form('revision-cafe-order',preferences+hidden(c,'total',cafeTotal(c))+`<label class="choice"><input type="checkbox" name="explicit" required><span>${esc(c,text(c,'explicit'))}</span></label>`+submit(c,'order'));
 return `<section class="cafefix-cart commerce-cart-source"><header class="commerce-cart-header" data-source="header_001"><div class="commerce-cart-title"><a class="icon-button" href="#discover/cafe" aria-label="${esc(c,text(c,'goMenu'))}">${glyph('lucide:x')}</a><h1 tabindex="-1">${esc(c,copy('Sepetim','Səbətim','Моя корзина'))}</h1><span aria-hidden="true"></span></div>${selectedVisit?`<article class="cafefix-active-visit" data-source="visit-context_002">${glyph('solar:calendar-mark-bold','visits')}<div><small>${esc(c,copy('Aktif ziyaret','Aktiv ziyarət','Текущий визит'))}</small><strong>${esc(c,visitLabel(c,selectedVisit))}</strong>${ui(c).cafeLocation?`<p>${esc(c,ui(c).cafeLocation)}</p>`:''}</div></article>`:''}</header><div class="commerce-cart-content" data-source="scroll-content_003"><div class="commerce-cart-items">${rowsMarkup}</div><div class="cafefix-cart-total" data-source="summary_005">${priced?`<dl class="commerce-cart-amounts"><div data-amount-role="subtotal"><dt>${esc(c,copy('Ara Toplam','Ara cəm','Промежуточная сумма'))}</dt><dd>${c.money(selectedItemsTotal)}</dd></div><div class="commerce-cart-fee-pending" data-amount-role="fee-information"><dt>${esc(c,copy('Ek ücret bilgisi','Əlavə ödəniş məlumatı','Информация о доплате'))}</dt><dd>${esc(c,copy('İşletme teyidi bekliyor','Müəssisənin təsdiqi gözlənilir','Ожидает подтверждения комплекса'))}</dd></div><div class="commerce-cart-items-total" data-amount-role="selected-items"><dt>${esc(c,copy('Seçilen ürünlerin toplamı','Seçilmiş məhsulların cəmi','Сумма выбранных товаров'))}</dt><dd>${c.money(selectedItemsTotal)}</dd></div></dl>`:`<p>${esc(c,unpriced)}</p>`}</div><p class="note commerce-cart-billing-note">${glyph('solar:info-circle-linear','rights')}<span>${esc(c,note)}</span></p>${controls}</div></section>`;
}
function cafeOrders(c,id){if(!c.cid()){c.requireAuth(id?'cafe-order/'+id:'cafe-orders');return '';}const copy={tracking:['Sipariş Takibi','Sifarişin izlənməsi','Статус заказа'],detail:['Sipariş Detayı','Sifariş məlumatı','Состав заказа'],pending:['Henüz gerçekleşmedi','Hələ baş verməyib','Ещё не выполнено'],posting:['Ücret yalnız teslimde ziyaret hesabına eklenir. Teslim, ödeme alındığı anlamına gelmez; hesap işletmede ayrıca kapatılır. Bu ekran yerel demo kayıtlarını gösterir.','Məbləğ yalnız təhvil zamanı ziyarət hesabına əlavə edilir. Təhvil ödəniş alındığı demək deyil; hesab məkanda ayrıca bağlanır. Bu ekran yerli demo qeydlərini göstərir.','Сумма добавляется в счёт визита только при выдаче. Выдача не означает оплату; счёт оплачивается отдельно на месте. Здесь показаны локальные демонстрационные записи.'],history:['İşlem geçmişi','Əməliyyat tarixçəsi','История действий']},word=k=>copy[k][['tr','az','ru'].indexOf(lang(c))],stages=['requested','approved','preparing','delivered'],list=rows(c,'cafeOrders').filter(x=>!id||x.id===id),focused=!!id&&list.length===1;return `<section class="cafefix-orders ${focused?'commerce-order-focused':''}">`+(focused?'':title(c,'orders','discover/cafe'))+(list.map(o=>`<article class="card revision-record cafefix-order"><header class="cafefix-order-header">${media('brand','default',{alt:'Sultan Saba'})}<p>${esc(c,word('tracking'))}</p><${focused?'h1':'h2'} tabindex="-1">${esc(c,text(c,o.status))}</${focused?'h1':'h2'}>${o.cancelRequested?badge(c,'cancel_requested'):''}</header>${stages.includes(o.status)?`<ol class="cafefix-order-timeline">${stages.map((stage,index)=>{const at=(o.history||[]).filter(x=>x.status===stage).at(-1)?.at,current=stage===o.status,reached=index<=stages.indexOf(o.status);return `<li class="${current?'is-current':reached?'is-complete':'is-upcoming'}" ${current?'aria-current="step"':''}><span class="cafefix-step-mark" aria-hidden="true"></span><div><strong>${esc(c,text(c,stage))}</strong>${at?`<time datetime="${esc(c,at)}">${esc(c,new Date(at).toLocaleTimeString(lang(c),{timeZone:'Asia/Baku',hour:'2-digit',minute:'2-digit'}))}</time>`:!reached?`<p>${esc(c,word('pending'))}</p>`:''}</div></li>`;}).join('')}</ol>`:badge(c,o.status)}<section class="cafefix-order-detail"><h3>${esc(c,word('detail'))}</h3><p>${esc(c,o.location||'')}</p><div class="revision-menu">${(o.items||[]).map(x=>`<div class="revision-menu-item"><span>${x.quantity} × ${esc(c,localized(c,x.snapshot||x))}</span><strong>${c.money((x.quantity||0)*(x.priceMinor||0))}</strong></div>`).join('')}</div><div class="cafefix-order-total"><span>${esc(c,text(c,'total'))}</span><strong>${c.money(o.totalMinor||0)}</strong></div>${o.reply?`<p class="note">${esc(c,o.reply)}</p>`:''}</section><p class="cafefix-posting-note">${esc(c,word('posting'))}</p><details class="cafefix-order-history"><summary>${esc(c,word('history'))}</summary>${history(c,o.history)}</details>${focused?'':a(c,'account','receipt/'+o.visitId,'secondary')}${!simplified(c)&&['requested','approved','preparing'].includes(o.status)&&!o.cancelRequested?form('revision-cafe-cancel',hidden(c,'id',o.id)+area(c,'reason')+submit(c,'cancel')):''}</article>`).join('')||empty(c))+a(c,'goMenu','discover/cafe','secondary')+`</section>`+(focused?`<footer class="flow-footer"><div class="commerce-order-footer">${a(c,'account','receipt/'+list[0].visitId,'secondary')}</div></footer>`:'');}
const eventWords={
organization:['Organizasyon','Təşkilat','Организация'],requestTitle:['Grup Etkinlik Talebi','Qrup Tədbiri Müraciəti','Заявка на групповое мероприятие'],quoteTitle:['Etkinlik Teklifi','Tədbir Təklifi','Предложение мероприятия'],planTitle:['Etkinlik Programı','Tədbir Planı','Программа мероприятия'],timing:['Zamanlama','Vaxt planı','Дата и время'],eventDetails:['Etkinlik ayrıntıları','Tədbir təfərrüatları','Детали мероприятия'],requestedScope:['Hizmet ve ikram isteğiniz','Xidmət və ikram istəyiniz','Пожелания по услугам и угощению'],scopeNote:['İsteğinizi yazın. Bu adımda hizmet veya ikram dahil edilmiş sayılmaz; kapsam teklifte ayrıca belirtilir.','İstəyinizi yazın. Bu addımda xidmət və ya ikram daxil edilmiş sayılmır; əhatə təklifdə ayrıca göstərilir.','Опишите пожелания. На этом этапе услуги и угощение не включены; состав будет указан в предложении.'],requestAction:['Teklif iste','Təklif istə','Запросить предложение'],requestNote:['Talebinizi resepsiyon inceler ve ayrı bir teklif sunar. Henüz alan, uzman veya tarih ayrılmaz.','Müraciəti resepsiya nəzərdən keçirir və ayrıca təklif verir. Hələ məkan, mütəxəssis və ya tarix rezervasiya olunmur.','Администратор рассмотрит заявку и подготовит предложение. Зоны, специалисты и дата пока не зарезервированы.'],itemized:['Hizmet kalemleri','Xidmət maddələri','Состав предложения'],allocations:['Planlanan tahsisler','Planlaşdırılan ayırmalar','Планируемые зоны и специалисты'],quoteNote:['Teklifi kabul etmeniz kesin rezervasyon değildir. Resepsiyon son uygunluk kontrolünden sonra planı onaylar; bu adımda ödeme alınmaz.','Təklifi qəbul etmək dəqiq rezervasiya deyil. Resepsiya son uyğunluq yoxlamasından sonra planı təsdiqləyir; bu addımda ödəniş alınmır.','Принятие предложения не создаёт подтверждённое бронирование. Администратор подтвердит план после итоговой проверки. На этом этапе оплата не взимается.'],expiredQuote:['Bu teklifin süresi doldu. Yeni teklif için resepsiyonla görüşün.','Bu təklifin müddəti bitib. Yeni təklif üçün resepsiyaya müraciət edin.','Срок предложения истёк. Обратитесь к администратору за новым предложением.'],acceptedNote:['Teklif kabul edildi; resepsiyonun son kontrolü bekleniyor.','Təklif qəbul edildi; resepsiyanın son yoxlaması gözlənilir.','Предложение принято; ожидается итоговая проверка администратора.'],confirmedPlan:['Program kesinleşti','Plan təsdiqləndi','Программа подтверждена'],confirmedNote:['Resepsiyonun onayladığı rezervasyon ve tahsis kayıtları aşağıda. Ödeme durumu ziyaret hesabında izlenir.','Resepsiyanın təsdiqlədiyi rezervasiya və ayırma qeydləri aşağıdadır. Ödəniş vəziyyəti ziyarət hesabında izlənir.','Ниже записи и зоны, подтверждённые администратором. Статус оплаты отображается в счёте визита.'],currentPlanTitle:['Mevcut onaylı program','Mövcud təsdiqli plan','Текущая подтверждённая программа'],proposalTitle:['Değişiklik teklifi','Dəyişiklik təklifi','Предложение изменений'],proposedNote:['Aşağıdaki teklif mevcut programdan ayrıdır. Yeni plan kesinleşene kadar önceki rezervasyonlar korunur.','Aşağıdakı təklif mövcud plandan ayrıdır. Yeni plan təsdiqlənənədək əvvəlki rezervasiyalar saxlanılır.','Предложение ниже отличается от текущей программы. До подтверждения нового плана прежние записи сохраняются.'],participant:['Katılımcı','İştirakçı','Участники'],organizer:['Organizatör','Təşkilatçı','Организатор'],organizerAbsent:['Organizatör katılmıyor','Təşkilatçı iştirak etmir','Организатор не участвует'],itinerary:['Akış planı','Tədbir axını','Расписание'],actualAllocations:['Kayıtlı tahsisler','Qeydə alınmış ayırmalar','Зарегистрированные зоны и специалисты'],noAllocations:['Ayrıntılı tahsis kaydı henüz yok.','Təfərrüatlı ayırma qeydi hələ yoxdur.','Подробных записей о зонах и специалистах пока нет.'],noRecord:['Bu etkinlik için kayıtlı rezervasyon bulunmuyor.','Bu tədbir üçün qeydə alınmış rezervasiya yoxdur.','Для этого мероприятия нет зарегистрированных записей.'],download:['Program özetini HTML olarak indir','Plan xülasəsini HTML kimi endir','Скачать программу в HTML'],downloadNote:['Kayıtlı programdan üretilen yazdırılabilir HTML dosyası.','Qeydə alınmış plandan yaradılmış çap edilə bilən HTML faylı.','Печатная HTML-версия зарегистрированной программы.'],changePlan:['Program değişikliği talebi','Plan dəyişikliyi müraciəti','Запросить изменение программы'],visitAccounts:['Bağlı ziyaret hesapları','Əlaqəli ziyarət hesabları','Связанные счета визитов'],capacity:['Ayrılan miktar','Ayrılmış miqdar','Выделено'],room:['alan','məkan','зон'],person:['kişi','nəfər','человек'],station:['yer','yer','мест'],expertUnknown:['Uzman bilgisi kayıtta yok','Mütəxəssis məlumatı qeyddə yoxdur','Специалист в записи не указан'],allocation:['Alan tahsisi','Məkan ayırması','Выделенная зона'],pastPlan:['Kayıtlı program','Qeydə alınmış plan','Зарегистрированная программа'],requestedAt:['Talep tarihi','Müraciət tarixi','Дата заявки'],myNote:['İsteğiniz','İstəyiniz','Ваши пожелания']};
